class Codec {
  serialize(root) {
    if (!root) return "[]";
    const out = [];
    const q = [root];
    while (q.length) {
      const node = q.shift();
      if (!node) {
        out.push("null");
        continue;
      }
      out.push(String(node.val));
      q.push(node.left ?? null, node.right ?? null);
    }
    while (out.length && out[out.length - 1] === "null") out.pop();
    return `[${out.join(",")}]`;
  }
  deserialize(data) {
    if (data === "[]") return null;
    const vals = data.slice(1, -1).split(",").map((x) => (x === "null" ? null : Number(x)));
    const nodes = vals.map((v) => (v === null ? null : { val: v, left: null, right: null }));
    const root = nodes[0];
    const q = [root];
    let i = 1;
    while (q.length && i < nodes.length) {
      const node = q.shift();
      if (!node) continue;
      if (i < nodes.length) {
        node.left = nodes[i];
        i += 1;
      }
      if (i < nodes.length) {
        node.right = nodes[i];
        i += 1;
      }
      if (node.left) q.push(node.left);
      if (node.right) q.push(node.right);
    }
    return root;
  }
}

